"""Analysis of an RTL run of an application generated by rttools.ucxgen
(CAR-V on the 4x4 manycore: experiments/car-v-rtl), against the phase
model of the analysis flow.

    python -m rttools.paper.rtlapp analyze <log> --manifest <name>.json --csv <app.csv> --map <app.map>
        --out <dir> [--run-info <RUN_INFO>] [--arch <arch.gml>] [--app <name> [--composition <file>]]
    python -m rttools.paper.exp23 check <dir>/metrics.json <reference.json>

The module generalizes rttools.paper.exp23 (application E, hand-written
weird_a.c) to any generated application: the tasks, flows, PEs and tags
come from the manifest of the generator, the costs and the period from the
CSV, the mapping from the .map file, the clock from the RUN_INFO of the
simulation (experiments/exp23/simulate.sh). No number of an application
is in this file.

A run of a composition (rttools.ucxgen compose: several applications on
disjoint PEs of one mesh, rttools.multiapp) holds the events of every
application. With --app, the analysis takes the manifest of that
application (rttools.ucxgen.model.app_manifest) and its CSV and .map: its
tasks, PEs, flows and tags; the tags and the packets of the other
applications are counted apart (tags.other_app_tags,
network.other_app_packets) and listed as contenders by
"<application>/f<flow>". The releases and their acknowledgments are those
of the whole image (one release generator period). With --composition
(the composition file of rttools.multiapp), the link schedule is the AGS
schedule of the union of the packets of every application at F_CLK.

Model (at the clock F_CLK of the run; P = T F_CLK cycles):

| Quantity | Definition | Source |
|---|---|---|
| s^(v), f^(v) | Start and finish of v in the sequence of its PE (ORT/BENCH on the costs c^(v) of the CSV, scheduler cost of #parameters) | release.task_windows |
| phi(v) | Phase index (one phase per edge between PEs; one on the same PE when the target runs before the source) | estimate.phases |
| R(v) | phi(v) P + f^(v) for each output task v (no output edge); R_bound = max over the output tasks, v_last its task | estimate.response_bound |
| t(V_k) | Sum of c^(v) of the tasks of PE k | estimate.demand |
| [r, d] of flow (u, v) | r = f^(u), d = P + s^(v), cycles from the start of the phase phi(u) of the iteration | release.phase_flows |
| L0 | 6 (m + 1) + p + 1, m = XY hops, p = payload flits of the packet | rttools.modules.routing.router |
| o_i | L0 + w_h (m + 1), w_h = header wait bound per router (router.header_wait) | router.occupancy |
| Link schedule (with --arch) | Start of the packet of each flow between PEs in the AGS schedule at F_CLK | search.schedule_at |

Measurement (log of the run):

| Quantity | Definition |
|---|---|
| r_k | k-th `TRIGGER: workflow iteration` line (release acknowledged by the lowest PE of the mask); `TRIGGER-PE` lines give the acknowledgment of the other PEs |
| Iteration of a packet | tag = flow tag_mod + (k mod tag_mod) (ucxgen); k unwrapped in time order per flow |
| End of iteration k of v | ITER end marker of v for k when the log has ITER lines; else the last send of v with iteration k (v with output edges); else (output task) the exit of v from the CPU after it has the packets of iteration k: exact when that run serves no later iteration, an upper bound otherwise |
| Response of iteration k | From r_k to the end of iteration k of every output task (the largest) |
| CPU per PE | Non-IDLE time of the PE in windows of phi(v_last) + 1 releases from r_{phi(v_last) + 1} (every phase holds an iteration), divided by phi(v_last) + 1; and, per task, the CPU time of its runs up to the end of its last complete iteration divided by the number of iterations |
| Packet against [r, d] | Send and receive (TAG lines) in cycles from r_k + phi(u) P |
| Network latency | FLIT lines of the packet monitor (rtl/pe_checker.sv): RX.last - TX.head; header = RX.head - TX.head against 6 (m + 1); TX and RX pair by source, destination and tag |
"""
from __future__ import annotations

import argparse
import bisect
import csv
import hashlib
import json
import math
import os
import re
import sys

from rttools.bench_t import estimate
from rttools.modules.instances import release
from rttools.modules.io import appparser
from rttools.modules.mapping import mapfile
from rttools.modules.routing import router
from rttools.paper import exp23
from rttools.tui.model import metrics as tmetrics

exact = exp23.exact


def num(x):
    """exact, then floats rounded to 1e-6 cycle (sums of half cycles of
    the snapped edges)."""
    x = exact(x)
    return round(x, 6) if isinstance(x, float) else x

RE_TRIGGER_PE = re.compile(r"TRIGGER-PE (\d+-\d+): release acknowledged at (\d+) ns")
RE_TRIGGER = re.compile(r"TRIGGER: workflow iteration at (\d+) ns")


# ------------------------------------------------------------ inputs

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()


def task_deadlines(csv_path):
    """{task: deadline in s} from the Deadline column of the #tasks section
    (legacy schema Task,Period,Capacity,Deadline,Acronym,...); {} without
    the column."""
    out, mode, col, lab = {}, 0, None, None
    with open(csv_path, newline="") as f:
        for row in csv.reader(f):
            if not row or not any(c.strip() for c in row):
                continue
            head = row[0].strip()
            if head.startswith("#"):
                mode = 1 if head == "#tasks" else 0
                continue
            if mode == 1:
                fields = [c.strip().lower() for c in row]
                col = fields.index("deadline") if "deadline" in fields else None
                lab = fields.index("acronym") if "acronym" in fields else None
                mode = 2 if col is not None and lab is not None else 0
                continue
            if mode == 2:
                out[row[lab].strip()] = float(row[col])
    return out


def load_app(manifest_path, csv_path, map_path, app_name=None):
    """Application of a run: the manifest of rttools.ucxgen, the costs and
    period of the CSV and the mapping of the .map file. ValueError when the
    manifest and the inputs disagree (tasks, flows, PEs). A manifest of a
    composition needs `app_name` (the application to analyze)."""
    with open(manifest_path) as f:
        man = json.load(f)
    other = None
    if man.get("apps"):
        from rttools.ucxgen import model as ucxmodel
        if app_name is None:
            raise ValueError("the manifest holds a composition (" + ", ".join(a["name"] for a in man["apps"])
                             + "); give the application (--app)")
        man = ucxmodel.app_manifest(man, app_name)
        other = {int(k): v for k, v in man["composition"]["other_flows"].items()}
    elif app_name is not None:
        raise ValueError("--app: the manifest holds one application")
    g, _ = appparser.loadFromFile(csv_path)
    entries = mapfile.read(map_path)
    tasks = [t["name"] for t in man["tasks"]]
    wcet = {t: int(d["wcet"]) for t, d in g.nodes(data=True)}
    if sorted(wcet) != sorted(tasks):
        raise ValueError("tasks of the manifest differ from the tasks of " + os.path.basename(csv_path))
    by_id = {fl["id"]: fl for fl in man["flows"]}
    pairs = [(fl["source"], fl["target"]) for fl in man["flows"]]
    if len(set(pairs)) != len(pairs):
        raise ValueError("two flows with the same source and target")
    edges = {(u, v): d for u, v, d in g.edges(data=True)}
    if set(edges) != set(pairs):
        raise ValueError("flows of the manifest differ from the flows of " + os.path.basename(csv_path))
    periods = {float(d["period"]) for d in edges.values()}
    if len(periods) != 1:
        raise ValueError("the application needs one release period")
    period_s = periods.pop()
    if round(period_s * 1e9) != man["release"]["period_ns"]:
        raise ValueError(f"period of the CSV {period_s} s differs from the manifest "
                         f"({man['release']['period_ns']} ns)")
    node_of = {t: int(e["node"]) for e in entries for t in e["tasks"]}
    for t in man["tasks"]:
        if node_of.get(t["name"]) != t["pe"]:
            raise ValueError(f"task {t['name']}: PE {t['pe']} of the manifest, {node_of.get(t['name'])} of the .map")
    width = man["mesh"][0]
    rel = release.settings(g.graph)
    if rel["model"] != release.PHASE:
        raise ValueError("the application does not use the phase model (release_model)")
    deadlines = task_deadlines(csv_path)
    out = {
        "manifest": man, "graph": g, "entries": entries, "tasks": tasks, "wcet": wcet,
        "flows": by_id, "period_s": period_s, "release": rel, "deadlines": deadlines,
        "label": {t["name"]: t["pe_label"] for t in man["tasks"]},
        "node_label": lambda n: f"{int(n) % width}-{int(n) // width}",
        "csv_path": csv_path,
        "inputs": {"csv": os.path.basename(csv_path), "map": os.path.basename(map_path),
                   "manifest": os.path.basename(manifest_path),
                   "csv_matches_manifest": sha256(csv_path) == man["inputs"]["csv"]["sha256"],
                   "map_matches_manifest": sha256(map_path) == man["inputs"]["map"]["sha256"]},
    }
    if other is not None:
        out["app_name"] = app_name
        out["other_flows"] = other
        out["inputs"]["composition"] = man["composition"]["name"]
        out["inputs"]["app"] = app_name
    return out


# ------------------------------------------------------------ model

def model(app, f_clk):
    """Phase model of the application at F_CLK (cycles)."""
    period = exact(app["period_s"] * f_clk)
    if not isinstance(period, int):
        raise ValueError(f"T F_CLK = {period} is not a whole number of cycles")
    man = app["manifest"]
    instance = {
        "tasks": [(t, {"wcet": app["wcet"][t]}) for t in app["tasks"]],
        "flows": [(fl["source"], fl["target"], {"label": fl["id"], "period": period})
                  for fl in man["flows"]],
        "release": app["release"],
    }
    entries = app["entries"]
    edges = [(fl["source"], fl["target"]) for fl in man["flows"]]
    win = release.task_windows(instance, entries)
    seqs = release.pe_sequences(app["tasks"], edges, entries, app["release"]["sequences"],
                                app["release"]["creation"])
    order = release.sequence_positions(seqs)
    pe_of = {t: win[t]["node"] for t in win}
    phi = estimate.phases(edges, pe_of, order)
    sinks = [t["name"] for t in man["tasks"] if not t["outputs"]]
    finish = {t: win[t]["finish"] for t in win}
    rb, vlast = estimate.response_bound(phi, finish, period, sinks)
    pf = release.phase_flows(instance, entries)
    lab = app["node_label"]
    dispatch = {lab(n): list(ts) for n, ts in seqs.items()}
    demand = {}
    for n, ts in seqs.items():
        demand[lab(n)] = estimate.demand([(t, app["wcet"][t]) for t in ts])
    sink_deadlines = [app["deadlines"][s] for s in sinks if s in app["deadlines"]]
    deadline_s = max(sink_deadlines) if sink_deadlines else None
    w_h = router.header_wait()
    return {
        "clock_hz": f_clk, "period_cycles": period,
        "tasks": {t: {"pe": lab(win[t]["node"]), "cost": app["wcet"][t], "start": win[t]["start"],
                      "finish": win[t]["finish"], "phase": phi[t]} for t in app["tasks"]},
        "dispatch": dispatch,
        "dispatch_matches_manifest": dispatch == {k: v for k, v in man["pe_dispatch"].items()},
        "outputs": {s: {"phase": phi[s], "finish": finish[s], "bound_cycles": phi[s] * period + finish[s]}
                    for s in sinks},
        "response_bound": {"cycles": rb, "ms": round(rb / f_clk * 1e3, 9), "task": vlast, "phase": phi[vlast]},
        "deadline": None if deadline_s is None else {
            "s": deadline_s, "ms": round(deadline_s * 1e3, 9), "cycles": exact(deadline_s * f_clk)},
        "demand_cycles": demand,
        "f_cpu_hz": exact(estimate.cpu_frequency(demand, app["period_s"])),
        "flows": {fid: {"release": pf[fid][0], "deadline": pf[fid][1]} for fid in app["flows"]},
        "header_wait_cycles": w_h,
    }


def link_schedule(app, arch_path, f_clk, composition=None):
    """Link schedule of the analysis flow at F_CLK (AGS backend,
    search.schedule_at, link occupancy o_i): start of the packet of each
    flow between PEs, cycles from the start of the phase of its source;
    {"feasible", "starts": {flow id: start}}. With `composition` (file of
    rttools.multiapp), the schedule of the union of the packets of every
    application of the composition (compose.schedule_union); the
    composition must place this application on the PEs of its .map file."""
    if composition is not None:
        return union_link_schedule(app, f_clk, composition)
    from rttools.modules.frequency import search
    from rttools.modules.io import nocparser
    from rttools.paper.frequency import search_config
    from rttools.tui.model import network as tnet
    with tnet.quiet():
        g, name = appparser.loadFromFile(app["csv_path"])
        noc = nocparser.loadFromFile(arch_path)
        a = search.schedule_at(g, noc, app["entries"], name, f_clk, search_config(f_clk))
    if a is None or a["schedule"] is None:
        return {"feasible": False, "starts": {}}
    by_label = {"f" + str(fl["csv_id"]): fid for fid, fl in app["flows"].items()}
    starts = {}
    for j, p in enumerate(a["problem"]["packets"]):
        vals = [row[j] for row in a["schedule"] if row[j] is not None]
        fid = by_label.get(p["flow"])
        if fid is not None and vals:
            starts[fid] = min(vals)
    return {"feasible": True, "skipped": len(a["skipped"]), "starts": starts}


def union_link_schedule(app, f_clk, composition):
    from rttools.multiapp import compose
    from rttools.paper.frequency import search_config
    from rttools.tui.model import network as tnet
    with tnet.quiet():
        comp = compose.load(compose.read_spec(composition))
    me = next((a for a in comp["apps"] if a["name"] == app.get("app_name")), None)
    if me is None:
        raise ValueError(f"application {app.get('app_name')} not in the composition {composition}")
    if mapfile.to_text(me["entries"]) != mapfile.to_text(app["entries"]):
        raise ValueError(f"the composition places {me['name']} on other PEs than its .map file")
    with tnet.quiet():
        a = compose.schedule_union(comp["apps"], comp["noc"], f_clk, search_config(f_clk))
    if a is None or a["schedule"] is None:
        return {"feasible": False, "starts": {}}
    by_label = {compose.qualify(me["name"], "f" + str(fl["csv_id"])): fid for fid, fl in app["flows"].items()}
    starts = {}
    for j, p in enumerate(a["problem"]["packets"]):
        vals = [row[j] for row in a["schedule"] if row[j] is not None]
        fid = by_label.get(p["flow"])
        if fid is not None and vals:
            starts[fid] = min(vals)
    return {"feasible": True, "skipped": len(a["skipped"]), "starts": starts, "union": True,
            "apps": [x["name"] for x in comp["apps"]]}


# ------------------------------------------------------------ log

def load_log(log_path, app, f_clk=None, run_info="auto"):
    """(trace, Clock, clock dict) of a log; the clock comes from the RUN_INFO
    (exp23.load_run), else f_clk."""
    cfg = {"pe_tasks": app["manifest"]["pe_tasks"], "release_period_s": app["period_s"],
           "clock_hz": f_clk}
    path = exp23.run_info_path(log_path) if run_info == "auto" else run_info
    if path is None and f_clk is None:
        raise ValueError("no RUN_INFO next to the log; give --f-clk")
    tr, _, clk, clock = exp23.load_run(log_path, cfg, None, path)
    return tr, clk, clock


def release_acks(log_path, app):
    """Acknowledgment of each release by the PEs of the mask (TRIGGER line
    of the lowest PE, TRIGGER-PE lines of the others): PEs per release
    against the PEs of the release mask of the manifest, and the spread of
    the acknowledgment instants (ns of the log)."""
    acks, trig = [], []
    with open(log_path, errors="replace") as f:
        for line in f:
            m = RE_TRIGGER_PE.search(line)
            if m:
                acks.append(int(m.group(2)))
                continue
            m = RE_TRIGGER.search(line)
            if m:
                trig.append(int(m.group(1)))
    per = [[t] for t in trig]
    for a in acks:
        if trig:
            per[min(range(len(trig)), key=lambda j: abs(trig[j] - a))].append(a)
    counts = [len(x) for x in per]
    spread = [max(x) - min(x) for x in per]
    return {"releases": len(trig), "pes_expected": len(app["manifest"]["release"]["pes"]),
            "pes_min": min(counts) if counts else None, "pes_max": max(counts) if counts else None,
            "spread_ns_max": max(spread) if spread else None}


def unwrap_iterations(kmods, mod):
    """Iterations k = 1, 2, ... of a sequence of k mod `mod` values in time
    order (tag = flow mod + (k mod mod)): each value is the next k with that
    residue after the previous k."""
    out, prev = [], 0
    for km in kmods:
        k = prev + 1 + (km - prev - 1) % mod
        out.append(k)
        prev = k
    return out


def tag_events(tr, app):
    """Send and receive of each packet by flow and iteration: {flow id:
    {"send": {k: t}, "recv": {k: t}, "send_lane", "recv_lane"}}, plus the
    counters of tags outside the flows, sends or receives on another PE than
    the manifest gives, repeated iterations and iterations that differ from
    the position of the packet in the flow (FIFO)."""
    man = app["manifest"]
    mod = man["tag_mod"]
    flows = app["flows"]
    ev = {fid: {"send": [], "recv": []} for fid in flows}
    unknown = lane_errors = other_app = 0
    other = app.get("other_flows") or {}
    for lane in tr.lanes:
        for mk in tr.lane_marks(lane):
            if mk.kind not in ("send", "recv") or not mk.label.startswith("TAG "):
                continue
            tag = int(mk.label.split()[1])
            fid = tag // mod
            if fid not in flows:
                if fid in other:
                    other_app += 1
                else:
                    unknown += 1
                continue
            fl = flows[fid]
            want = fl["src_label"] if mk.kind == "send" else fl["dst_label"]
            if lane != want:
                lane_errors += 1
            ev[fid][mk.kind].append((mk.time, tag % mod))
    out = {}
    repeated = mismatch = 0
    for fid, d in ev.items():
        o = {}
        for kind in ("send", "recv"):
            ks = {}
            evs = sorted(d[kind])
            for pos, ((t, _), k) in enumerate(zip(evs, unwrap_iterations([km for _, km in evs], mod)), start=1):
                if k in ks:
                    repeated += 1
                ks[k] = t
                mismatch += k != pos
            o[kind] = ks
        out[fid] = o
    counts = {"unknown_tags": unknown, "lane_errors": lane_errors, "repeated": repeated,
              "fifo_mismatch": mismatch}
    if "other_flows" in app:
        counts["other_app_tags"] = other_app
    return out, counts


def iteration_marks(tr, app):
    """{task: {k: {"begin", "end"}}} from ITER lines (letter of the task in
    the manifest, field iter_letter); {} without ITER lines."""
    letters = {(t["pe_label"], t.get("iter_letter")): t["name"] for t in app["manifest"]["tasks"]
               if t.get("iter_letter")}
    out = {}
    for m in tr.meta.get("iterations") or []:
        name = letters.get((m["lane"], m["task"]))
        if name is None:
            continue
        it = out.setdefault(name, {}).setdefault(m["iteration"], {"begin": None, "end": None})
        if it[m["edge"]] is not None:
            raise ValueError(f"repeated ITER {m['edge']} {name} {m['iteration']}")
        it[m["edge"]] = m["time"]
    return out


def _run_index(runs, t):
    """Index of the run (start, end) with start <= t <= end, else None."""
    starts = [a for a, _ in runs]
    i = bisect.bisect_right(starts, t) - 1
    if i >= 0 and runs[i][0] <= t <= runs[i][1]:
        return i
    return None


def task_iterations(tr, app, mdl, clk, releases, ev, marks):
    """End of each iteration of each task, the run of the CPU that holds it,
    the observed phase and the CPU time per iteration."""
    man = app["manifest"]
    period = mdl["period_cycles"]
    out = {}
    r_of = {k: r for k, r in enumerate(releases, start=1)}
    for t in man["tasks"]:
        v, lane = t["name"], t["pe_label"]
        runs = exp23.closed_runs(tr, lane, v)
        ready = {}
        for k, r in r_of.items():
            if not t["inputs"]:
                ready[k] = r
            else:
                ts = [ev[f]["recv"].get(k) for f in t["inputs"]]
                if all(x is not None for x in ts):
                    ready[k] = max(ts)
        rows = {}
        if v in marks:
            source = "markers"
            for k, mk in sorted(marks[v].items()):
                if mk["end"] is None:
                    continue
                rows[k] = {"end": mk["end"], "begin": mk["begin"], "exact": True,
                           "run": _run_index(runs, mk["end"])}
        elif t["outputs"]:
            source = "last_send"
            ks = set.intersection(*(set(ev[f]["send"]) for f in t["outputs"]))
            for k in sorted(ks):
                e = max(ev[f]["send"][k] for f in t["outputs"])
                rows[k] = {"end": e, "begin": None, "exact": True, "run": _run_index(runs, e)}
        else:
            source = "run_exit"
            for k in sorted(ready):
                a = ready[k]
                i = next((j for j, (_, e) in enumerate(runs) if e > a), None)
                if i is None:
                    break
                rows[k] = {"end": runs[i][1], "begin": None, "exact": None, "run": i,
                           "lower": max(a, runs[i][0])}
            for k, row in rows.items():
                row["exact"] = not any(rows[j]["run"] == row["run"] for j in rows if j > k)
        per_run = {}
        for k, row in rows.items():
            per_run.setdefault(row["run"], []).append(k)
        same = sorted(k for k, row in rows.items() if k - 1 in rows and row["run"] is not None
                      and rows[k - 1]["run"] == row["run"])
        lat = []
        phases = {}
        for k, row in rows.items():
            if k not in r_of:
                continue
            off = clk.cycles(row["end"] - r_of[k])
            row["end_cycles"] = exact(off)
            q = int(math.floor(off / period))
            row["phase"] = q
            phases[q] = phases.get(q, 0) + 1
            lat.append(exact(off - (mdl["tasks"][v]["phase"] * period + mdl["tasks"][v]["finish"])))
        complete = sorted(rows)
        cpu = None
        if complete and r_of:
            last = rows[complete[-1]]
            end = runs[last["run"]][1] if last["run"] is not None else last["end"]
            busy = sum(e - s for s, e in runs if s >= r_of[1] and e <= end)
            n = len([k for k in complete if rows[k]["end"] <= end])
            cpu = num(clk.cycles(busy) / n) if n else None
        out[v] = {"pe": lane, "source": source, "rows": rows, "iterations": len(rows),
                  "same_run_as_previous": same, "runs_with_iterations": len(per_run),
                  "max_iterations_per_run": max((len(x) for x in per_run.values()), default=0),
                  "phase_model": mdl["tasks"][v]["phase"], "phase_observed": dict(sorted(phases.items())),
                  "end_minus_model_finish_max": max(lat) if lat else None,
                  "ends_after_model_finish": sum(1 for x in lat if x > 0),
                  "cpu_per_iteration_cycles": cpu, "cost": mdl["tasks"][v]["cost"]}
    return out


def responses(app, mdl, clk, releases, its):
    """Response of each iteration: from r_k to the end of iteration k of
    every output task (the largest)."""
    sinks = list(mdl["outputs"])
    rows = []
    for k, r in enumerate(releases, start=1):
        per = {}
        for s in sinks:
            row = its[s]["rows"].get(k)
            if row is None:
                break
            per[s] = {"cycles": exact(clk.cycles(row["end"] - r)), "exact": bool(row["exact"]),
                      "lower_cycles": exact(clk.cycles(row["lower"] - r)) if "lower" in row else None}
        if len(per) != len(sinks):
            break
        worst = max(sinks, key=lambda s: per[s]["cycles"])
        lower = max(per[s]["lower_cycles"] if per[s]["lower_cycles"] is not None else per[s]["cycles"]
                    for s in sinks)
        rows.append({"iteration": k, "task": worst, "response_cycles": per[worst]["cycles"],
                     "response_ms": round(per[worst]["cycles"] / mdl["clock_hz"] * 1e3, 9),
                     "exact": per[worst]["exact"] and all(per[s]["exact"] or per[s]["cycles"] < per[worst]["cycles"]
                                                          for s in sinks),
                     "lower_cycles": lower, "outputs": per})
    rb = mdl["response_bound"]["cycles"]
    dl = mdl["deadline"]["cycles"] if mdl["deadline"] else None
    ex = [x["response_cycles"] for x in rows if x["exact"]]
    up = [x["response_cycles"] for x in rows if not x["exact"]]
    allv = [x["response_cycles"] for x in rows]
    s = {
        "complete": len(rows), "exact": len(ex), "upper_bound_only": len(up),
        "max_cycles": max(allv) if allv else None,
        "max_ms": round(max(allv) / mdl["clock_hz"] * 1e3, 9) if allv else None,
        "max_exact_cycles": max(ex) if ex else None,
        "max_upper_cycles": max(up) if up else None,
        "max_lower_cycles": max(x["lower_cycles"] for x in rows) if rows else None,
        "above_bound": sum(1 for v in allv if v > rb),
        "exact_above_bound": sum(1 for v in ex if v > rb),
        "lower_above_bound": sum(1 for x in rows if x["lower_cycles"] > rb),
        "margin_bound_exact_cycles": rb - max(ex) if ex else None,
        "margin_bound_all_cycles": rb - max(allv) if allv else None,
        "above_deadline": None if dl is None else sum(1 for v in allv if v > dl),
        "margin_deadline_cycles": None if dl is None or not allv else dl - max(allv),
        "rows": rows,
    }
    return s


def cpu_windows(tr, app, mdl, clk, releases):
    """CPU time of each PE in windows of phi(v_last) + 1 releases from
    r_{phi(v_last) + 1}, per iteration, against t(V_k)."""
    n = mdl["response_bound"]["phase"] + 1
    p_raw = clk.raw(app["period_s"])
    wins = []
    s = n - 1   # index of r_{phi(v_last) + 1}
    while s < len(releases):
        a = releases[s]
        b = releases[s + n] if s + n < len(releases) else a + n * p_raw
        if b > tr.t1:
            break
        wins.append((a, b, s + 1))
        s += n
    # phases [r_k, r_k+1) from r_{phi(v_last) + 1} while the log covers them
    phases = []
    for k in range(n - 1, len(releases)):
        a = releases[k]
        b = releases[k + 1] if k + 1 < len(releases) else a + p_raw
        if b <= tr.t1:
            phases.append((a, b))
    pes = {}
    for pe, demand in mdl["demand_cycles"].items():
        per = [num(clk.cycles(tmetrics.lane_stats(tr, pe, a, b).busy) / n) for a, b, _ in wins]
        mean = num(sum(per) / len(per)) if per else None
        phase = [num(clk.cycles(tmetrics.lane_stats(tr, pe, a, b).busy)) for a, b in phases]
        pes[pe] = {"estimated": demand, "per_window": per, "mean": mean,
                   "overestimation_percent": None if not mean else 100 * (demand - mean) / mean,
                   "phase_busy_max": max(phase) if phase else None,
                   "phases_above_estimate": sum(1 for v in phase if v > demand),
                   "tasks": [t for t in mdl["dispatch"][pe]]}
    over = [p["overestimation_percent"] for p in pes.values() if p["overestimation_percent"] is not None]
    return {"releases_per_window": n, "windows": [{"first_release": k, "start_ms": clk.ms(a), "end_ms": clk.ms(b)}
                                                  for a, b, k in wins],
            "phases": len(phases), "pes": pes, "mean_overestimation_percent": sum(over) / len(over) if over else None,
            "min_overestimation_percent": min(over) if over else None}


def cpu_attributed(mdl, its):
    """CPU per iteration of each PE from the runs of its tasks
    (task_iterations: cpu_per_iteration_cycles), against t(V_k)."""
    out = {}
    for pe, ts in mdl["dispatch"].items():
        vals = [its[t]["cpu_per_iteration_cycles"] for t in ts]
        if any(v is None for v in vals):
            out[pe] = None
            continue
        m = num(sum(vals))
        d = mdl["demand_cycles"][pe]
        out[pe] = {"measured": m, "estimated": d, "overestimation_percent": 100 * (d - m) / m}
    return out


def packets(app, mdl, clk, releases, ev):
    """Send and arrival of each packet against the window [r, d] of its
    flow, in cycles from r_k + phi(source) P."""
    period = mdl["period_cycles"]
    out = []
    for fid, fl in sorted(app["flows"].items()):
        w = mdl["flows"][fid]
        shift = mdl["tasks"][fl["source"]]["phase"] * period
        rows = []
        for k, ts in sorted(ev[fid]["send"].items()):
            if k > len(releases):
                continue
            r = releases[k - 1]
            sc = exact(clk.cycles(ts - r) - shift)
            tr_ = ev[fid]["recv"].get(k)
            ac = exact(clk.cycles(tr_ - r) - shift) if tr_ is not None else None
            rows.append({"flow": fid, "iteration": k, "send_cycles": sc, "arrival_cycles": ac,
                         "slack_cycles": None if ac is None else exact(w["deadline"] - ac)})
        send = [x["send_cycles"] for x in rows]
        arr = [x["arrival_cycles"] for x in rows if x["arrival_cycles"] is not None]
        slack = [x["slack_cycles"] for x in rows if x["slack_cycles"] is not None]
        out.append({"flow": fid, "source": fl["source"], "target": fl["target"], "local": fl["local"],
                    "src_pe": fl["src_label"], "dst_pe": fl["dst_label"], "bytes": fl["bytes"],
                    "release": w["release"], "deadline": w["deadline"], "phase": mdl["tasks"][fl["source"]]["phase"],
                    "packets": len(rows), "received": len(arr),
                    "send_min": min(send) if send else None, "send_max": max(send) if send else None,
                    "arrival_min": min(arr) if arr else None, "arrival_max": max(arr) if arr else None,
                    "sent_before_phase": sum(1 for v in send if v < 0),
                    "sent_after_release": sum(1 for v in send if v > w["release"]),
                    "late": sum(1 for v in slack if v < 0),
                    "min_slack_cycles": min(slack) if slack else None, "rows": rows})
    remote = [f for f in out if not f["local"]]
    return {"flows": out,
            "packets": sum(f["packets"] for f in out),
            "remote_packets": sum(f["packets"] for f in remote),
            "late": sum(f["late"] for f in out),
            "min_slack_remote_cycles": min((f["min_slack_cycles"] for f in remote
                                            if f["min_slack_cycles"] is not None), default=None)}


# ------------------------------------------------------------ network

def xy_links(src, dst):
    """Directed links of the XY route (X first) from router src to router dst,
    plus the ejection port of dst: [("x-y", "x-y"), ..., ("x-y", "local")]."""
    (x, y), (bx, by) = (tuple(int(v) for v in n.split("-")) for n in (src, dst))
    out = []
    while x != bx:
        nx_ = x + (1 if bx > x else -1)
        out.append((f"{x}-{y}", f"{nx_}-{y}"))
        x = nx_
    while y != by:
        ny = y + (1 if by > y else -1)
        out.append((f"{x}-{y}", f"{x}-{ny}"))
        y = ny
    out.append((dst, "local"))
    return out


def network(log_path, app, mdl, clk, ev, schedule=None):
    """Network latency of each packet from the FLIT lines, by flow; header
    wait (header > 6 (m + 1)) and the packets that held a link of the route
    at the time (contenders)."""
    with open(log_path, errors="replace") as f:
        tx, rx = exp23.parse_flit_lines(f)
    if not tx and not rx:
        return None
    mod = app["manifest"]["tag_mod"]
    w_h = mdl["header_wait_cycles"]
    q = {}
    for t in sorted(tx, key=lambda d: d["head"]):
        q.setdefault((t["src"], t["dst"], t["tag"]), []).append(t)
    pk, unpaired_rx = [], 0
    for r in sorted(rx, key=lambda d: d["last"]):
        lst = q.get((r["src"], r["dst"], r["tag"]))
        if not lst:
            unpaired_rx += 1
            continue
        t = lst.pop(0)
        fid, km = t["tag"] // mod, t["tag"] % mod
        fl = app["flows"].get(fid)
        oth = (app.get("other_flows") or {}).get(fid)
        m = exp23._hops(t["src"], t["dst"])
        p = t["size"]
        hop = router.getRoutingTime() * (m + 1)
        L0 = hop + p + 1
        lat = r["last"] - t["head"]
        head = r["head"] - t["head"]
        pk.append({"flow": fid if fl else None, "tag": t["tag"], "k_mod": km, "src": t["src"], "dst": t["dst"],
                   "hops": m, "size": p,
                   "size_model": router.getPacketFlits(fl["bytes"]) if fl else None,
                   "tx_head": t["head"], "tx_last": t["last"], "rx_head": r["head"], "rx_last": r["last"],
                   "latency": lat, "L0": L0, "latency_minus_L0": lat - L0, "header": head,
                   "header_minus_model": head - hop, "occupancy": L0 + w_h * (m + 1),
                   "latency_minus_occupancy": lat - (L0 + w_h * (m + 1)),
                   "stall": r.get("stall"), "gap": r.get("gap"), "tx_block": t.get("block"), "tx_gap": t.get("gap"),
                   "identity_ok": (r["last"] - r["head"] == p + 1 + r.get("stall", 0) + r.get("gap", 0)
                                   and t["last"] - t["head"] == p + 1 + t.get("block", 0) + t.get("gap", 0)),
                   "links": xy_links(t["src"], t["dst"]), "other": oth})
    unpaired_tx = sum(len(v) for v in q.values())
    # iteration of each packet (unwrap per flow in order of the header)
    for x in pk:
        x["iteration"] = None
    for fid in {x["flow"] for x in pk if x["flow"] is not None}:
        xs = sorted((x for x in pk if x["flow"] == fid), key=lambda x: x["tx_head"])
        for x, k in zip(xs, unwrap_iterations([x["k_mod"] for x in xs], mod)):
            x["iteration"] = k
    # contenders: other packets that share a link of the route and hold the
    # path while the header of this one waits
    for x in pk:
        x["contenders"] = []
        x["contenders_other"] = []
        if x["header_minus_model"] <= 0:
            continue
        links = set(x["links"])
        for y in pk:
            if y is x or y["tx_head"] > x["rx_head"] or y["rx_last"] < x["tx_head"]:
                continue
            if links & set(y["links"]):
                x["contenders"].append(y["flow"])
                if y["other"] is not None:
                    x["contenders_other"].append(y["other"])
    # software latency (TAG lines) against the network latency
    for x in pk:
        sw = None
        if x["flow"] is not None and x["iteration"] is not None:
            a = ev[x["flow"]]["send"].get(x["iteration"])
            b = ev[x["flow"]]["recv"].get(x["iteration"])
            if a is not None and b is not None:
                sw = exact(clk.cycles(b - a))
        x["software_latency"] = sw
        x["driver"] = None if sw is None else exact(sw - x["latency"])
    flows = []
    for fid, fl in sorted(app["flows"].items()):
        if fl["local"]:
            continue
        xs = [x for x in pk if x["flow"] == fid]
        m = exp23._hops(fl["src_label"], fl["dst_label"])
        p = router.getPacketFlits(fl["bytes"])
        hop = router.getRoutingTime() * (m + 1)
        row = {"flow": fid, "source": fl["source"], "target": fl["target"], "src_pe": fl["src_label"],
               "dst_pe": fl["dst_label"], "hops": m, "flits": p, "L0": hop + p + 1, "header_model": hop,
               "occupancy": hop + p + 1 + w_h * (m + 1), "header_wait_bound": w_h * (m + 1),
               "window": mdl["flows"][fid]["deadline"] - mdl["flows"][fid]["release"],
               "schedule_start": (schedule or {}).get("starts", {}).get(fid),
               "packets": len(xs),
               "size_mismatch": sum(1 for x in xs if x["size"] != p),
               "header_waits": sum(1 for x in xs if x["header_minus_model"] > 0),
               "header_waits_above_bound": sum(1 for x in xs if x["header_minus_model"] > w_h * (m + 1)),
               "above_occupancy": sum(1 for x in xs if x["latency_minus_occupancy"] > 0),
               "contender_flows": sorted({c for x in xs for c in x["contenders"] if c is not None})}
        if "other_flows" in app:
            row["contender_other_apps"] = sorted({c for x in xs for c in x["contenders_other"]})
        for k in ("latency", "latency_minus_L0", "header_minus_model", "stall", "gap", "tx_block",
                  "software_latency", "driver"):
            vals = [x[k] for x in xs if x[k] is not None]
            row[k + "_min"], row[k + "_max"] = (min(vals), max(vals)) if vals else (None, None)
        flows.append(row)
    # the packets of the other applications of a composition stay out of
    # the counts (they appear as contenders only)
    own = [x for x in pk if x["other"] is None]
    out = {
        "model": "L0 = 6 (m + 1) + p + 1; header 6 (m + 1); o_i = L0 + w_h (m + 1)",
        "header_wait_cycles": w_h,
        "tx": len(tx), "rx": len(rx), "packets": len(own), "unpaired_tx": unpaired_tx, "unpaired_rx": unpaired_rx,
        "outside_flows": sum(1 for x in own if x["flow"] is None),
        "identity_errors": sum(1 for x in own if not x["identity_ok"]),
        "header_waits": sum(1 for x in own if x["header_minus_model"] > 0),
        "header_waits_above_bound": sum(1 for x in own if x["header_minus_model"] > w_h * (x["hops"] + 1)),
        "above_occupancy": sum(1 for x in own if x["latency_minus_occupancy"] > 0),
        "flows": flows,
        "per_packet": own,
    }
    if "other_flows" in app:
        out["other_app_packets"] = len(pk) - len(own)
        out["header_waits_with_other_app_contender"] = sum(1 for x in own if x["contenders_other"])
    return out


# ------------------------------------------------------------ outputs

def _csv(path, rows, cols):
    with open(path, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(cols)
        for r in rows:
            w.writerow([r.get(c) for c in cols])


def analyze(log_path, manifest_path, csv_path, map_path, out_dir, run_info="auto", f_clk=None, arch=None,
            app_name=None, composition=None):
    app = load_app(manifest_path, csv_path, map_path, app_name)
    tr, clk, clock = load_log(log_path, app, f_clk, run_info)
    if tr.meta.get("swap_xy"):
        raise ValueError("the PE labels of the log are swapped against the manifest")
    mdl = model(app, clock["clock_hz"])
    releases = sorted(m.time for m in tr.lane_marks("TRIGGER"))
    if not releases:
        raise ValueError("no TRIGGER lines (releases) in the log")
    ev, tagc = tag_events(tr, app)
    marks = iteration_marks(tr, app)
    its = task_iterations(tr, app, mdl, clk, releases, ev, marks)
    resp = responses(app, mdl, clk, releases, its)
    win = cpu_windows(tr, app, mdl, clk, releases)
    att = cpu_attributed(mdl, its)
    pkts = packets(app, mdl, clk, releases, ev)
    sched = link_schedule(app, arch, clock["clock_hz"], composition) if (arch or composition) else None
    if sched:
        for f in pkts["flows"]:
            f["schedule_start"] = sched["starts"].get(f["flow"])
    net = network(log_path, app, mdl, clk, ev, sched)
    per_packet = net.pop("per_packet") if net else []
    r2d = []
    for k, r in enumerate(releases, start=1):
        firsts = []
        for t in app["manifest"]["tasks"]:
            if t["inputs"]:
                continue
            st = [s.start for s in tr.lane_slices(t["pe_label"]) if s.label == t["name"] and s.start >= r]
            if st:
                firsts.append(min(st))
        if firsts:
            r2d.append(exact(clk.cycles(min(firsts) - r)))
    m = {
        "log": os.path.basename(log_path),
        "inputs": app["inputs"],
        "clock": clock,
        "unit": {"name": tr.unit.name, "detected": tr.meta["timescale_detected"],
                 "swap_xy": bool(tr.meta["swap_xy"])},
        "model": {k: v for k, v in mdl.items() if k != "tasks"},
        "model_tasks": mdl["tasks"],
        "releases": {"count": len(releases), "first_ms": clk.ms(releases[0]),
                     "period_cycles_min": exact(min(clk.cycles(b - a) for a, b in zip(releases, releases[1:])))
                     if len(releases) > 1 else None,
                     "period_cycles_max": exact(max(clk.cycles(b - a) for a, b in zip(releases, releases[1:])))
                     if len(releases) > 1 else None,
                     "release_to_first_dispatch_min_cycles": min(r2d) if r2d else None,
                     "release_to_first_dispatch_max_cycles": max(r2d) if r2d else None,
                     "acks": release_acks(log_path, app)},
        "tags": tagc,
        "markers": len(tr.meta.get("iterations") or []),
        "iteration_source": {v: d["source"] for v, d in its.items()},
        "tasks": {v: {k: d[k] for k in d if k != "rows"} for v, d in its.items()},
        "responses": resp,
        "cpu_windows": win,
        "cpu_attributed": att,
        "packets": {k: v for k, v in pkts.items()},
        "network": net,
        "link_schedule": None if sched is None else {k: v for k, v in sched.items()},
        "monitor": exp23.monitor_summary(log_path),
    }
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "metrics.json"), "w") as f:
        json.dump(m, f, indent=1, default=str)
    _csv(os.path.join(out_dir, "responses.csv"),
         [{k: r[k] for k in ("iteration", "task", "response_cycles", "response_ms", "exact", "lower_cycles")}
          for r in resp["rows"]],
         ["iteration", "task", "response_cycles", "response_ms", "exact", "lower_cycles"])
    _csv(os.path.join(out_dir, "packets.csv"), [r for f in pkts["flows"] for r in f["rows"]],
         ["flow", "iteration", "send_cycles", "arrival_cycles", "slack_cycles"])
    _csv(os.path.join(out_dir, "flows.csv"), pkts["flows"],
         ["flow", "source", "target", "local", "src_pe", "dst_pe", "bytes", "phase", "release", "deadline",
          "packets", "send_min", "send_max", "arrival_max", "min_slack_cycles", "sent_after_release",
          "sent_before_phase", "late", "schedule_start"])
    _csv(os.path.join(out_dir, "cpu.csv"),
         [dict(pe=pe, tasks=" ".join(p["tasks"]), estimated=p["estimated"], mean=p["mean"],
               overestimation_percent=p["overestimation_percent"],
               attributed=(att[pe] or {}).get("measured")) for pe, p in win["pes"].items()],
         ["pe", "tasks", "estimated", "mean", "overestimation_percent", "attributed"])
    _csv(os.path.join(out_dir, "tasks.csv"),
         [dict(task=v, **{k: d[k] for k in ("pe", "source", "iterations", "phase_model", "cost",
                                             "cpu_per_iteration_cycles", "end_minus_model_finish_max",
                                             "ends_after_model_finish", "max_iterations_per_run")},
               phase_observed=" ".join(f"{a}:{b}" for a, b in d["phase_observed"].items()),
               same_run=" ".join(map(str, d["same_run_as_previous"]))) for v, d in its.items()],
         ["task", "pe", "source", "iterations", "phase_model", "phase_observed", "cost",
          "cpu_per_iteration_cycles", "end_minus_model_finish_max", "ends_after_model_finish",
          "max_iterations_per_run", "same_run"])
    if net:
        _csv(os.path.join(out_dir, "network.csv"), net["flows"], list(net["flows"][0]) if net["flows"] else [])
        cols = [c for c in per_packet[0] if c not in ("links", "other", "contenders_other")] if per_packet else []
        _csv(os.path.join(out_dir, "network_packets.csv"), per_packet, cols)
    return m


def summary_lines(m):
    mdl = m["model"]
    rb = mdl["response_bound"]
    r = m["responses"]
    out = [f"{m['log']}: F_CLK {exp23.mhz_text(m['clock']['clock_hz'])} MHz from {m['clock']['source']}, "
           f"P {mdl['period_cycles']:,} cycles, {m['releases']['count']} releases, {m['markers']} ITER lines",
           f"  R_bound {rb['cycles']:,} cycles ({rb['ms']:.3f} ms, {rb['task']}, phase {rb['phase']}); "
           f"deadline {mdl['deadline']['ms'] if mdl['deadline'] else '-'} ms",
           f"  responses: {r['complete']} iterations ({r['exact']} exact, {r['upper_bound_only']} upper bound); "
           f"max {r['max_cycles']:,} cycles; max exact {r['max_exact_cycles']}; above R_bound {r['above_bound']} "
           f"(exact {r['exact_above_bound']}, lower bound {r['lower_above_bound']}); above deadline {r['above_deadline']}"]
    for pe, p in m["cpu_windows"]["pes"].items():
        a = m["cpu_attributed"].get(pe)
        out.append(f"  PE {pe} ({' '.join(p['tasks'])}): t(V) {p['estimated']:,}, measured {p['per_window']} "
                   f"mean {p['mean']} ({p['overestimation_percent']:+.2f}%)"
                   + (f", attributed {a['measured']} ({a['overestimation_percent']:+.2f}%)" if a else ""))
    pk = m["packets"]
    out.append(f"  packets: {pk['packets']} ({pk['remote_packets']} between PEs), late {pk['late']}, "
               f"min slack between PEs {pk['min_slack_remote_cycles']}")
    net = m["network"]
    if net:
        out.append(f"  network: {net['packets']} packets, {net['header_waits']} with header wait "
                   f"({net['header_waits_above_bound']} above w_h (m + 1)), {net['above_occupancy']} above o_i, "
                   f"{net['identity_errors']} identity errors")
    mon = m["monitor"]
    out.append("  monitor: " + ("no CHKSUM lines" if mon is None else
                                f"{mon['errors']} errors, {mon['send_pkts']} sent, {mon['recv_pkts']} received "
                                f"({mon['nodes']} PEs)"))
    return out


def main(argv=None):
    p = argparse.ArgumentParser(prog="rttools.paper.rtlapp", description=__doc__.split("\n\n")[0])
    sub = p.add_subparsers(dest="cmd", required=True)
    a = sub.add_parser("analyze")
    a.add_argument("log")
    a.add_argument("--manifest", required=True)
    a.add_argument("--csv", required=True)
    a.add_argument("--map", required=True)
    a.add_argument("--out", required=True)
    a.add_argument("--run-info", default="auto", help="RUN_INFO of the run (default: next to the log)")
    a.add_argument("--f-clk", type=int, default=None, help="F_CLK (Hz) when the log has no RUN_INFO")
    a.add_argument("--arch", default=None,
                   help="architecture (.gml) for the link schedule of the analysis flow at F_CLK (AGS)")
    a.add_argument("--app", default=None,
                   help="application of a composition (manifest of rttools.ucxgen compose)")
    a.add_argument("--composition", default=None,
                   help="composition file (rttools.multiapp): link schedule of the union of the packets")
    args = p.parse_args(argv)
    m = analyze(args.log, args.manifest, args.csv, args.map, args.out, args.run_info, args.f_clk, args.arch,
                args.app, args.composition)
    for line in summary_lines(m):
        print(line)
    print("wrote " + args.out)
    return 0


if __name__ == "__main__":
    sys.exit(main())
